20.query:
timeseries value = avg(aerospike_namespace_data_used_pct, filter: { cluster_name == $cluster and in(service, array($node)) and in(ns, array($namespace)) }), by: { cluster_name, ns, service, storage_engine }
| sort arrayAvg(value) desc
| limit 10
| fieldsRename data_used = value
| append [
  timeseries value = avg(aerospike_namespace_data_avail_pct, filter: { cluster_name == $cluster and in(service, array($node)) and in(ns, array($namespace)) }), by: { cluster_name, ns, service, storage_engine }
  | sort arrayAvg(value) desc
  | limit 10
  | fieldsRename data_available = value
]

21.query:
timeseries a0 = avg(aerospike_latencies_write_ms_bucket, filter: { cluster_name == $cluster and in(service, array($node)) and in(ns, array($namespace)) and le == "+Inf" }), a1 = avg(aerospike_latencies_write_ms_bucket, filter: { cluster_name == $cluster and in(service, array($node)) and in(ns, array($namespace)) and le == $latency_time_bucket }), by: { cluster_name, ns, service }
| fieldsAdd value = (a0[] - a1[])
| fieldsRemove a0, a1

22.query:
timeseries a0 = sum(aerospike_namespace_storage_engine_device_defrag_reads, filter: { cluster_name == $cluster and in(service, array($node)) and in(ns, array($namespace)) }), a1 = sum(aerospike_namespace_storage_engine_device_defrag_writes, filter: { cluster_name == $cluster and in(service, array($node)) and in(ns, array($namespace)) }), by: { cluster_name, device, device_index, ns, service, storage_engine }
| fieldsAdd device_reads = a0[], writes = a1[], writes_ = a1[]
| fieldsRemove a0, a1

